import type {GuideSection} from './guide-details';

type Workshop={formula:string;heading:string;context:string;steps:string[];columns:string[];rows:(string|number)[][];interpretation:string;check:string;question:string;answer:string};
const fixed=(n:number,places=3)=>Number(n.toFixed(places));
const gearingRows=(pairs:[number,number][],baseline:number)=>pairs.map(([front,rear])=>[`${front}/${rear}`,fixed(rear/front),fixed((rear/front/baseline-1)*100,2),fixed((baseline/(rear/front)-1)*100,2)]);
const gearingColumns=['Front / rear teeth','Final reduction (:1)','Reduction change (%)','Fixed-RPM speed change (%)'];
export const guideWorkshops:Record<string,Workshop>={
 'calculate-go-kart-gear-ratios':{formula:'R = rear teeth / front teeth; axle RPM = engine RPM / R',heading:'Build a go-kart gearing worksheet',context:'Start with a direct-drive example so that each input has a clear meaning. The table compares three sprocket pairs against a 12/60 baseline, holding engine RPM, tires and all other stages unchanged. The reduction percentage describes ideal torque multiplication at equal engine torque; the speed percentage uses the reciprocal ratio.',steps:['Record the driving sprocket as front and the axle sprocket as rear; count teeth rather than judging their diameters.','Divide rear by front. Multiply any additional stage reductions only after this chain ratio is established.','Divide loaded engine RPM by the complete reduction to find wheel RPM, then use tire circumference for road speed.','Keep the old setup and proposed setup together in your notes so a later tire or converter change does not invalidate the comparison.'],columns:gearingColumns,rows:gearingRows([[12,60],[12,66],[12,72]],5),interpretation:'The 12/66 pair gives 5.5:1. Compared with 5:1, it increases reduction by 10%, while fixed-RPM speed falls by 9.09%. That is a useful directional comparison for gearing a go-kart for acceleration, but it is not a measured acceleration improvement. The engine can deliver a different torque when the new ratio moves it to a different RPM.',check:'If the rear tooth count increases and the worksheet shows a lower reduction, check whether you inverted front and rear. If the tooth-count ratio is right but MPH is far too high, check the tire unit and every converter or jackshaft stage before changing the sprockets.',question:'How do I compare two kart ratios without knowing tire size?',answer:'Divide the new rear/front ratio by the old rear/front ratio. Tire size is unnecessary for the percentage change when it remains unchanged. You still need tire circumference and RPM for an absolute speed.'},
 'go-kart-gear-ratio-chart':{formula:'R = rear/front; MPH = engine RPM × π × diameter(in) / (1,056 × R)',heading:'Turn a gear chart into a repeatable comparison',context:'This compact chart uses a fixed 12-tooth driver, 3,600 engine rpm and 13-inch nominal tire diameter. It isolates rear sprocket choices. The speed column assumes a direct chain drive without converter slip or an extra stage; adding either changes the complete engine-to-wheel reduction.',steps:['Check whether the row lists rear teeth or front teeth before reading the crossing cell.','Write RPM, nominal diameter and total additional reduction above the chart.','Read across one row or down one column to change one sprocket at a time.','Regenerate speed cells whenever the operating RPM, tire dimensions or converter ratio changes.'],columns:['Front / rear','Reduction (:1)','Axle RPM','Theoretical MPH'],rows:[60,66,72].map(rear=>[`12/${rear}`,rear/12,3600/(rear/12),fixed(3600*Math.PI*13/(1056*(rear/12)),2)]),interpretation:'A chart containing both ratio and MPH answers two different questions. Ratio depends only on teeth; MPH also depends on wheel travel and engine RPM. Two combinations with the same ratio can share speed cells while having different physical sprocket sizes and chain-length requirements.',check:'A printed chart is easy to reuse after its assumptions have changed. Keep a dated copy with the setup it describes. Do not interpret a speed cell as proof that the engine will achieve the chosen RPM on the longest straight.',question:'Why does a gear-ratio chart need engine RPM?',answer:'The ratio cells do not need RPM. A chart needs engine RPM only when it also converts the ratio into axle RPM or theoretical road speed.'},
 'go-kart-acceleration-vs-top-speed':{formula:'Torque factor = Rnew/Rold; fixed-RPM speed factor = Rold/Rnew',heading:'Quantify the acceleration and speed trade-off',context:'Use a 5:1 baseline and compare progressively larger reductions. The table holds engine torque and engine RPM equal to separate the ideal mechanical effects. A real kart does not necessarily maintain either input while accelerating, which is why these percentages should be interpreted as gearing changes rather than lap-time predictions.',steps:['Choose the existing reduction as the baseline and identify where the kart struggles on the course.','Calculate the new/old ratio quotient to compare ideal torque multiplication.','Invert that quotient to compare speed at the same engine RPM.','Record whether the change alters corner-exit RPM, a shift or converter operating point, or the time spent at an RPM limit.'],columns:['New reduction (:1)','Ideal torque change (%)','Speed change at equal RPM (%)'],rows:[5,5.5,6].map(r=>[r,fixed((r/5-1)*100,2),fixed((5/r-1)*100,2)]),interpretation:'The two percentage columns are deliberately different. A 6:1 setup has 20% more reduction than 5:1, while speed at equal RPM drops 16.67%. If traction already limits the kart, the extra ideal torque may not translate into a faster exit. If the engine was below its useful range, the altered RPM can matter more than the simple torque percentage.',check:'Compare observations from the same track section and similar conditions. A faster straight-end speed accompanied by a slower corner exit is a trade-off to investigate, not enough evidence to declare a universally better ratio.',question:'Which ratio change should I try for a short kart track?',answer:'First compare the existing setup with a small, physically suitable increase in reduction and examine corner-exit and straight-end RPM. Track length alone does not specify an optimum ratio.'},
 'go-kart-sprocket-sizes':{formula:'Change (%) = (new reduction / old reduction − 1) × 100',heading:'Compare front and rear sprocket changes fairly',context:'The baseline below is 12/60. Compare one added rear tooth with one removed front tooth before assuming that a one-tooth change has a fixed effect. Both options increase numerical reduction, but the small driver makes the front-tooth change a larger fraction of its original size.',steps:['Calculate the baseline ratio using the actual tooth counts.','Calculate the complete proposed ratio, including both new sprockets if both are changing.','Compare reduction and inverse speed quotients instead of subtracting tooth numbers.','Use the chain-length calculator and equipment documentation to assess the changed chain path and available adjustment.'],columns:gearingColumns,rows:gearingRows([[12,60],[12,61],[11,60]],5),interpretation:'Adding one rear tooth increases reduction by about 1.67%; removing one front tooth increases it by about 9.09%. Equal tooth changes are therefore not equivalent gearing adjustments. If you seek a small comparison step, calculate the percentage before choosing between front and rear options.',check:'Do not infer compatible pitch, width, mounting or ground clearance from the ratio. A physically larger rear sprocket can change clearances even when the numerical reduction matches another pair.',question:'Can different sprocket sizes produce exactly the same gearing?',answer:'Yes. For example, 12/60 and 14/70 both give 5:1. They still require separate checks of chain length, sprocket mounting, chain specification and clearance.'},
 'go-kart-speed-from-rpm':{formula:'Wheel RPM = engine RPM/R; speed(m/s) = wheel RPM × circumference(m)/60',heading:'Follow engine RPM through to kart road speed',context:'Keep reduction at 5:1 and nominal tire diameter at 13 inches while engine RPM changes. The table describes a geometric relationship, so doubling the RPM doubles speed. It does not estimate the available power or identify the highest RPM the engine can maintain under load.',steps:['Enter loaded engine RPM, or clearly label an assumed RPM as a scenario.','Include every reduction between the measured shaft and the driven wheel.','Convert nominal diameter to circumference with πD, or use an appropriate measured rolling circumference.','Convert distance per minute to MPH or km/h once, keeping minutes and hours visible in the calculation.'],columns:['Engine RPM','Wheel RPM','Theoretical MPH'],rows:[3000,3600,4200].map(n=>[n,n/5,fixed(n*Math.PI*13/(1056*5),2)]),interpretation:'A lower observed speed can arise from lower loaded RPM, a different converter operating point or rolling dimensions that differ from the entered nominal diameter. Check those inputs before attributing every discrepancy to drag or a calculation error. The worksheet maps a chosen operating point; it does not solve which operating point the kart will reach.',check:'The conversion from inches per minute to miles per hour divides by 1,056. If you entered circumference, do not multiply by π again. If your input is already wheel RPM, do not divide it by the engine-to-wheel ratio a second time.',question:'Does a kart speed calculator include clutch slip?',answer:'This geometric calculation assumes the entered ratio is transmitted without slip. Compare the RPM of the relevant shafts or use a documented operating ratio if you need to investigate a mismatch.'},
 'go-kart-jackshaft-gearing':{formula:'Rtotal = (B/A) × (D/C); nJ = nEngine/(B/A)',heading:'Calculate each jackshaft stage in order',context:'Let A be the engine sprocket, B the jackshaft input, C the jackshaft output and D the axle sprocket. Hold A = 12, B = 18 and C = 12 below, varying D. This separates the first-stage 1.5:1 reduction from the second-stage tooth ratio.',steps:['Trace the first chain from engine sprocket A to jackshaft sprocket B.','Trace the second chain from jackshaft sprocket C to axle sprocket D.','Multiply B/A by D/C for overall reduction; do not add the stage ratios.','Calculate jackshaft RPM after stage one, then axle RPM after stage two to check the direction of both quotients.'],columns:['Axle sprocket D','First stage (:1)','Overall (:1)','Axle RPM at 3,600'],rows:[48,60,72].map(d=>[d,1.5,1.5*d/12,3600/(1.5*d/12)]),interpretation:'The jackshaft turns at 2,400 rpm for every row because the first stage is unchanged. Only the second stage and axle RPM change. This distinction helps when comparing two layouts that have the same total ratio but place different speeds on the intermediate shaft.',check:'An idler on one chain is not the same arrangement as a compound shaft carrying separate input and output sprockets. Confirm that the two jackshaft sprockets are fixed to the same shaft and identify any converter before multiplying another stage.',question:'Why can two jackshaft layouts share total reduction but have different jackshaft RPM?',answer:'Overall reduction is the product of both stages. You can change the first stage and compensate in the second; the product stays the same while the intermediate shaft speed changes.'},
 'go-kart-torque-converter-ratios':{formula:'Rtotal = Rchain × Rconverter at the selected operating point',heading:'Compare launch and running converter scenarios',context:'The example fixes chain reduction at 5:1, engine RPM at 3,600 and nominal tire diameter at 13 inches. Converter ratios below are illustrative input scenarios, not specifications for any product. Holding RPM constant is a deliberate way to isolate geometric ratio effects.',steps:['Find documented operating ratios for your exact converter and identify the convention used for reduction.','Multiply each selected converter reduction by the complete chain and jackshaft reduction.','Calculate wheel speed separately for each operating point rather than averaging the ratios first.','Record the engine RPM associated with the operating point when moving from a comparison to actual observations.'],columns:['Selected converter (:1)','Overall reduction (:1)','Theoretical MPH'],rows:[2.5,1,0.9].map(c=>[c,5*c,fixed(3600*Math.PI*13/(1056*5*c),2)]),interpretation:'The 0.9:1 scenario is an overdrive relative to the converter input, so overall reduction becomes 4.5:1. The selected converter ratio does not describe belt slip, engagement or the rate of shifting. A single static number cannot capture the complete acceleration process.',check:'Do not apply a launch ratio to every speed calculation, or assume that a no-load observed ratio holds under load. A converter description such as high or low range needs actual numerical ratios before it can be entered meaningfully.',question:'Can I average converter ratios to predict a complete acceleration run?',answer:'Not with this static worksheet. Acceleration also depends on how the ratio and engine output change with time and load. Evaluate clearly labeled operating points instead.'},
 'go-kart-chain-sizes':{formula:'Nominal pitch = measured pin-center span / number of intervals',heading:'Measure pitch without miscounting the pins',context:'A pitch measurement spans the spaces between pin centers, not the count of visible pins. The table uses ten intervals, which require eleven consecutive pin centers. It illustrates nominal spacing only and does not specify a chain family, roller size, working load or wear limit.',steps:['Identify chain markings and the manufacturer specification before relying on a ruler measurement.','Choose two pin centers several intervals apart and count the spaces between them.','Divide the center-to-center span by the number of intervals to estimate pitch.','Compare nominal pitch, width, roller dimensions and the specified sprocket tooth form separately.'],columns:['Nominal pitch (in)','Intervals','Nominal span (in)','Pitch (mm)'],rows:[0.25,0.375,0.5].map(p=>[p,10,p*10,p*25.4]),interpretation:'For a 0.375-inch pitch, ten intervals span 3.75 inches in the nominal geometry. Counting eleven pins and dividing by eleven would give a smaller, incorrect pitch. Wear and measurement uncertainty can also make a real span differ from this ideal value.',check:'Pitch identification and chain-length selection are separate tasks. Identify the correct chain system first, then use both sprocket tooth counts and shaft center distance to estimate the number of pitches needed for the loop.',question:'Can wear make a chain look like a different pitch?',answer:'Wear can increase the measured span, so a worn sample alone is an unreliable basis for nominal identification. Compare markings and documented dimensions rather than inventing a new nominal size from the measurement.'},
 'mini-bike-gear-ratios':{formula:'Travel per engine turn = tire circumference / overall reduction',heading:'Compare mini-bike reduction and wheel travel together',context:'A 6:1 ratio describes the RPM reduction but not the distance traveled for each engine turn. The following cases hold reduction and engine RPM at 6:1 and 3,600 while nominal tire diameter changes. Converter and jackshaft stages are assumed already included in the overall reduction.',steps:['List the chain, jackshaft and converter stages and calculate their product.','Record the nominal tire diameter or measured rolling circumference used for the comparison.','Divide engine RPM by the complete reduction to obtain wheel RPM.','Compare distance traveled per engine turn before interpreting a gearing label such as tall or low.'],columns:['Nominal tire diameter (in)','Wheel RPM','Theoretical MPH'],rows:[13,16,19].map(d=>[d,600,fixed(600*Math.PI*d/1056,2)]),interpretation:'The wheel turns at 600 rpm in all three rows, but a larger tire travels farther each turn. This is why two mini bikes with the same sprocket ratio can have different calculated speeds. The larger tire also changes contact-patch force for a given wheel torque, so the comparison is more than a dashboard number.',check:'Do not treat a tire designation as an exact rolling dimension. Also verify that a nominal chain-only ratio has not been mistaken for the complete engine-to-wheel ratio when a converter or extra stage is installed.',question:'How can two mini bikes with the same gearing have different speed?',answer:'They can have different rolling circumferences, engine RPM or converter operating ratios. The tooth-count ratio alone does not determine distance per minute.'},
 'mini-bike-sprocket-selection':{formula:'Rold = rear/front; Rnew = new rear/new front',heading:'Compare a mini-bike sprocket change with a baseline',context:'Use the existing 12/60 pair as a baseline and hold tires and other stages fixed. The table separates a modest rear-tooth change from a larger front-tooth change. A meaningful mini-bike sprocket comparison uses complete ratios, even when the proposed change looks small.',steps:['Count the existing driver and driven teeth, and record the ratio.','Enter the proposed pair and calculate its complete quotient.','Compare new/old reduction and old/new fixed-RPM speed, labeling both percentage changes.','Check chain specification, mounting, chain path and available adjustment before treating the proposed pair as a usable option.'],columns:gearingColumns,rows:gearingRows([[12,60],[12,66],[11,60]],5),interpretation:'Changing the rear from 60 to 66 teeth adds 10% reduction. Removing one tooth from the driver adds about 9.09%, a similar but different numerical change. Matching percentage effects do not imply identical articulation, chain length or clearance.',check:'If a proposed setup calculates more speed, ask whether the engine can still reach the same loaded RPM. The spreadsheet comparison assumes equal RPM; it does not determine clutch loading or the torque curve.',question:'Can I compare a driver change and a rear-sprocket change in the same worksheet?',answer:'Yes. Calculate each proposed rear/front ratio against the same original pair. Compare the reduction and reciprocal speed percentages before examining physical fit.'},
 'mini-bike-top-speed':{formula:'MPH = engine RPM × π × tire diameter(in) / (1,056 × total reduction)',heading:'Build a mini-bike speed range from stated assumptions',context:'The table fixes engine RPM at 3,600 and nominal diameter at 19 inches, varying only complete reduction. A range of scenarios makes the gearing effect visible without presenting the largest theoretical number as attainable top speed.',steps:['Identify whether engine RPM is measured under load or an assumed scenario input.','Include any primary, jackshaft and selected converter reductions.','Calculate geometric speed for the original ratio and each proposed ratio using the same rolling dimension.','Compare observed RPM and speed together; a different loaded RPM can reverse the expected benefit of taller gearing.'],columns:['Overall reduction (:1)','Wheel RPM','Theoretical MPH'],rows:[6,7.5,9].map(r=>[r,fixed(3600/r,2),fixed(3600*Math.PI*19/(1056*r),2)]),interpretation:'At unchanged RPM, 7.5:1 gives 80% of the speed of 6:1. A real mini bike may reach different RPM with those two reductions because resistance and available engine output determine its operating point. The table is a transparent comparison of geometry, not a power or resistance model.',check:'Distinguish measured rolling circumference from nominal tire diameter and record the converter ratio used. Do not use an attainable-speed claim to infer that the frame, brakes or tires are rated for that speed.',question:'What should I record when calculated mini-bike speed differs from observed speed?',answer:'Record synchronized loaded engine RPM, independent road speed, selected gear or converter operating point, complete reduction and rolling circumference. Those inputs help locate the mismatch.'},
 'motorcycle-sprocket-ratio':{formula:'Rtotal = primary reduction × selected gear × rear/front',heading:'Calculate final drive and overall motorcycle reduction',context:'Hold primary reduction at 1.8:1 and selected transmission gear at 1:1. The table shows how changing final sprockets changes overall reduction. These primary and gearbox values illustrate the arithmetic; they are not specifications for any motorcycle.',steps:['Obtain primary and selected-gear reductions from the exact model documentation.','Calculate final reduction as rear teeth divided by front teeth.','Multiply all stages to calculate engine-to-wheel reduction.','Use engine RPM divided by that complete product before applying rolling circumference.'],columns:['Front / rear','Final reduction (:1)','Overall reduction (:1)','Wheel RPM at 6,000'],rows:[45,48,51].map(rear=>[`15/${rear}`,rear/15,fixed(1.8*rear/15),fixed(6000/(1.8*rear/15),2)]),interpretation:'With 15/45 sprockets, the final stage is 3:1 while the complete reduction in this example is 5.4:1. Changing gear alters the complete reduction without changing sprockets. Keep the term final drive separate from overall gearing when comparing RPM or road speed.',check:'A model-specific primary ratio or transmission ratio cannot be guessed from the front and rear teeth. Verify the exact gear and model year, and keep physical chain compatibility separate from the mathematical speed relationship.',question:'Do I need the primary ratio for a percentage-only sprocket comparison?',answer:'Not if primary drive, selected gear and tire circumference remain unchanged. They cancel in the new/old quotient. You need them for an absolute engine-to-wheel speed calculation.'},
 'motorcycle-gearing-acceleration':{formula:'Ideal torque factor = new final reduction / old final reduction',heading:'Compare sprocket changes without promising acceleration gains',context:'The table uses 15/45 as the baseline and holds the engine operating point and other stages equal. It shows ideal ratio changes; it cannot predict traction, wheel lift or the shift sequence during an actual acceleration run.',steps:['Calculate both final reductions and compare their quotient.','Calculate the inverse quotient for speed at the same RPM and transmission gear.','Check how the new final ratio moves engine RPM at a target road speed.','Consider whether an extra shift occurs before the comparison point and whether traction limits the available force.'],columns:gearingColumns,rows:gearingRows([[15,45],[15,48],[14,45]],3),interpretation:'A higher reduction gives more wheel torque at the same engine torque, but that condition may not hold at the same road speed. The new gearing changes engine RPM and therefore the torque available on the engine curve. Comparing only the ratio percentages omits this operating-point effect.',check:'Do not describe a 6.67% reduction increase as a measured 6.67% acceleration increase. Keep a record of the gear, RPM range and shift points involved in the comparison, then examine chain fit and manufacturer limits independently.',question:'Why can shorter motorcycle gearing add a shift before a target speed?',answer:'Higher reduction raises engine RPM at each road speed in the same gear. The engine can reach its usable RPM limit at a lower road speed, moving the next shift earlier.'},
 'motorcycle-highway-rpm':{formula:'New RPM = old RPM × (Rnew/Rold) × (old circumference/new circumference)',heading:'Estimate cruising RPM after a sprocket change',context:'Use a measured 5,000 rpm baseline with 15/45 sprockets and unchanged tires, primary drive and selected cruising gear. This isolates the final-drive effect without needing to know every unchanged stage individually.',steps:['Record actual engine RPM at a chosen steady road speed and identify the selected gear.','Calculate existing and proposed rear/front ratios.','Multiply the observed RPM by new ratio divided by old ratio.','If rolling circumference also changes, multiply by old circumference divided by new circumference before comparing the result.'],columns:['Front / rear','Final reduction (:1)','Engine RPM at same road speed'],rows:[[15,45],[16,45],[15,48]].map(([f,r])=>[`${f}/${r}`,fixed(r/f),fixed(5000*(r/f)/3,1)]),interpretation:'The 16/45 pair changes final reduction from 3 to 2.8125, so RPM at the same road speed becomes 93.75% of the original. The calculation describes the RPM relationship, not fuel consumption, vibration or how readily the engine will pull the gear on a grade.',check:'Compare the same road speed and selected transmission gear. A different gear or tire circumference can overwhelm the sprocket-only percentage. A speedometer recalibrated from drivetrain rotation is not necessarily an independent check.',question:'Can I estimate RPM change from a measured baseline without tire diameter?',answer:'Yes, when rolling circumference and all other stages remain unchanged. Multiply baseline RPM by the quotient of the new and old final-drive reductions.'},
 'motorcycle-chain-length':{formula:'L(pitches) ≈ 2C/p + (N₁+N₂)/2 + (N₂−N₁)²/(4π² C/p)',heading:'Check selected link count against shaft adjustment',context:'For equal 20-tooth sprockets, the difference-of-teeth term is zero. With half-inch pitch, the table compares selected even pitch counts and the idealized center distance they require. This simplified case exposes what link rounding does to fit.',steps:['Measure shaft center distance and use the same length unit for it and chain pitch.','Calculate fractional chain pitches from both sprocket counts and the entered spacing.','Select the appropriate buildable count and solve again for its associated center distance.','Compare the result with available adjustment, the exact chain specification and the manufacturer tensioning procedure.'],columns:['Selected pitches','Chain length (in)','Ideal center distance (in)'],rows:[60,62,64].map(l=>[l,l*0.5,(l-20)*0.5/2]),interpretation:'Adding two pitches of half-inch chain adds one inch to loop length. In this equal-sprocket case it increases ideal center distance by half an inch because both straight spans become longer. Unequal sprockets include an additional term and should be recalculated rather than assuming this exact shortcut.',check:'A static center-distance calculation does not establish correct chain slack through suspension travel. It also omits tensioners and idlers. Keep those physical requirements separate from a nominal two-sprocket length estimate.',question:'Why does adding an inch of chain change center distance by only about half an inch?',answer:'An open two-sprocket loop has two straight spans. Increasing shaft spacing lengthens both. For equal sprockets, the ideal formula gives exactly half the loop-length increase as center-distance increase.'},
 'dirt-bike-gearing':{formula:'Rtotal = Rprimary × Rgear × (rear/front); wheel RPM = engine RPM/Rtotal',heading:'Work out dirt-bike gearing for trail and track',context:'Start with a 14-tooth front and 49-tooth rear as a 3.5:1 final-drive baseline. Compare nearby pairs while holding primary drive, selected transmission gear, tire circumference and engine RPM unchanged. This makes a dirt-bike sprocket change for tight trails understandable without implying that one ratio suits every bike or surface.',steps:['Count the installed front and rear teeth and record the selected transmission gear. Use the exact model documentation for primary and gearbox ratios.','Calculate final reduction as rear/front, then multiply primary and selected-gear reductions for an absolute RPM-to-speed calculation.','Calculate new/old final reduction for the ideal torque-multiplication change. Invert the quotient for fixed-RPM speed.','Identify the terrain section you want to improve, recording which gear and RPM you use there rather than changing several setup variables at once.','Check whether the new gearing moves a shift into a difficult section or reaches the usable RPM limit too early on faster terrain.','Assess chain path, guide and slider interaction, chain length and available adjustment using the equipment instructions before treating a mathematical option as installed fitment.'],columns:gearingColumns,rows:gearingRows([[14,49],[14,52],[13,49]],3.5),interpretation:'Changing to 14/52 raises final reduction by 6.12%, while speed in the same gear at equal RPM falls by 5.77%. Changing to 13/49 produces a larger 7.69% reduction increase and a 7.14% fixed-RPM speed decrease. Neither figure predicts an equal acceleration improvement. On loose ground, wheelspin can consume the extra wheel torque without increasing ground speed. On a faster section, the earlier shift can offset a benefit noticed in a slow corner.',check:'Distinguish wheel speed from ground speed when testing dirt-bike gearing on loose terrain. A wheel spinning over a rut or slick surface breaks the no-slip conversion used by the calculator. Compare repeatable sections, keep tire pressure and load states documented, and avoid attributing every GPS/RPM mismatch to an incorrect ratio. This model does not select a safe engine-speed limit or component rating.',question:'What gearing is better for technical dirt-bike trails?',answer:'More reduction can provide a lower speed at a useful engine RPM, but the useful change depends on the original setup, engine curve, selected gear, traction and terrain. Calculate a specific proposed pair against your current pair and inspect its effect on shift points and fit.'},
 'dirt-bike-sprocket-selection':{formula:'Reduction factor = (new rear/new front) / (old rear/old front)',heading:'Choose a comparison step using percentages',context:'Use 14/49 as the baseline below. The comparison demonstrates why replacing a front sprocket by one tooth is not the same change as adding one tooth at the rear. All other stages and tire dimensions are held fixed.',steps:['Record the original tooth pair and divide rear by front.','Calculate each proposed complete ratio, including both sprockets if both change.','Compare the quotient rather than adding independent front and rear tooth percentages.','Check whether the intended chain length, slider and guide arrangement remain suitable for the new physical path.'],columns:gearingColumns,rows:gearingRows([[14,49],[13,49],[14,50]],3.5),interpretation:'A 14/50 pair gives only a 2.04% increase in reduction relative to 14/49, while 13/49 gives 7.69%. If you are trying to distinguish a small setup change from a large one, these proportions are more useful than the phrase one tooth. The table does not imply that the smaller driver is suitable for the actual chain-slider arrangement.',check:'A calculation does not check articulation, wear, mounting or clearance. Keep the tooth-count comparison with the current chain specification and inspect the parts documentation before purchasing a proposed combination.',question:'How can I make a smaller numerical gearing change on a dirt bike?',answer:'Compare nearby rear-tooth options with front-tooth options using complete ratios. A single rear tooth is often a smaller proportional step because the rear sprocket has more teeth, but actual suitability still requires a fit check.'},
 'gear-ratio-speed-formula':{formula:'v(m/s) = engine RPM × circumference(m) / (60 × overall reduction)',heading:'Track the units through the road-speed equation',context:'The example fixes engine speed at 3,000 rpm and tire diameter at 0.6 m while overall reduction changes. These are abstract values for checking the unit cancellation; they do not represent a particular vehicle or attainable speed.',steps:['Convert diameter to meters before using v in meters per second, or use a measured circumference directly.','Divide RPM by overall reduction to obtain wheel revolutions per minute.','Multiply by circumference to obtain meters per minute, then divide by 60.','Multiply meters per second by 3.6 for km/h, or divide by 0.44704 for MPH.'],columns:['Overall reduction (:1)','Wheel RPM','Speed (m/s)','Speed (km/h)'],rows:[3,4,5].map(r=>[r,3000/r,fixed(3000*Math.PI*0.6/(60*r)),fixed(3000*Math.PI*0.6/(60*r)*3.6,2)]),interpretation:'At 4:1, wheel speed is 750 rpm and theoretical road speed is approximately 84.82 km/h. Increasing reduction to 5:1 reduces the result by a factor of 4/5. The formula contains no mass, engine torque or drag term, so its output should not be presented as an acceleration or power-limited maximum-speed prediction.',check:'The circumference input already describes distance traveled per revolution. Multiplying it by π again is a common diameter/circumference mix-up. Confirm the measured shaft for the RPM input before applying any reduction.',question:'How do I use measured tire circumference in the speed formula?',answer:'Use v = RPM × circumference/(60R), with circumference in meters for v in m/s. Do not multiply measured circumference by π; that step is only needed when starting from diameter.'},
 'gear-ratio-from-rpm':{formula:'R = engine RPM × circumference(m) / (60 × road speed(m/s))',heading:'Infer overall reduction from synchronized measurements',context:'Hold engine RPM at 3,600 and nominal diameter at 13 inches, then compare different independently measured road speeds. At the same engine speed, a higher road speed implies a smaller reduction under the no-slip fixed-ratio model.',steps:['Record engine RPM and independent road speed together at a steady operating point.','Convert road speed into meters per second and circumference into meters.','Rearrange the wheel-travel relationship to calculate overall reduction.','Repeat at other steady operating points to check consistency before interpreting a result as a fixed mechanical ratio.'],columns:['Road speed (MPH)','Engine RPM','Inferred overall reduction (:1)'],rows:[25,30,35].map(mph=>[mph,3600,fixed(3600*Math.PI*13/(1056*mph))]),interpretation:'The inferred quotient contains every stage between the measured engine shaft and the driven wheel. It cannot identify final drive by itself if primary and gearbox reductions are unknown. A changing result can indicate a variable converter, slip, tire measurement error or unsynchronized readings, rather than a changing fixed gear set.',check:'If the displayed road speed already derives from drivetrain rotation and an assumed circumference, the input may not provide independent evidence. State the speed measurement method and avoid reading RPM and speed at different moments during acceleration.',question:'Why do repeated RPM-and-speed measurements give different gear ratios?',answer:'Check synchronized timing, rolling circumference and the selected gear first. Converter ratio change, clutch slip, wheelspin or measurement error can also make the fixed-ratio inference inconsistent.'},
 'final-drive-ratio':{formula:'Rfinal = driven teeth/driving teeth; Rtotal = Rgearbox × Rfinal × other stages',heading:'Compare a final-drive ratio with overall gearing',context:'The following axle ratios use the same selected transmission overdrive of 0.75:1 and no other stages. This separates final reduction from the engine-to-wheel quotient needed for road-speed calculations.',steps:['Identify whether the final stage is a chain pair or a ring-and-pinion set.','Divide driven teeth by driving teeth, retaining the actual quotient when counts are known.','Multiply by the selected gearbox ratio and any other reduction stages.','Use overall reduction, rather than final drive alone, when converting engine RPM to wheel RPM.'],columns:['Final ratio (:1)','Selected gear (:1)','Overall reduction (:1)','Wheel RPM at 3,000'],rows:[3.5,4.1,4.5].map(r=>[r,0.75,fixed(r*0.75),fixed(3000/(r*0.75),2)]),interpretation:'With a 4.10 final drive and 0.75 selected gear, overall reduction is 3.075:1. Applying 4.10 alone would overstate the engine RPM needed for a given wheel speed in that gear. A higher final-drive number is more reduction; words such as taller or lower should be accompanied by the actual numerical convention.',check:'A ratio describes rotational speed relationships and ideal torque multiplication. It does not establish tooth strength, efficiency, differential action or compatibility with a particular axle or chain system.',question:'Does an overdrive gear cancel the final-drive ratio?',answer:'It multiplies it by a value below one rather than removing it. A 0.75 overdrive with 4.10 final drive produces 3.075 overall when no other stages apply.'},
 'rpm-to-mph':{formula:'MPH = engine RPM × circumference(in) / (1,056 × overall reduction)',heading:'Convert wheel revolutions into miles per hour',context:'For a 13-inch nominal tire, circumference is approximately 40.8407 inches. The table fixes wheel RPM and shows equivalent engine RPM for a 5:1 overall reduction. Keeping both shaft speeds visible helps expose which RPM belongs in the formula.',steps:['Identify whether the RPM measurement is at the engine, an intermediate shaft or the wheel.','Convert the measured shaft speed to wheel RPM using the intervening reduction only.','Multiply wheel RPM by circumference in inches for inches per minute.','Divide by 1,056 to convert inches per minute to miles per hour.'],columns:['Wheel RPM','Engine RPM at 5:1','Theoretical MPH'],rows:[600,720,900].map(w=>[w,w*5,fixed(w*Math.PI*13/1056,2)]),interpretation:'At 720 wheel rpm, the nominal travel corresponds to about 27.85 MPH. At the same road speed, the engine would be at 3,600 rpm with 5:1 overall reduction. A direct wheel-RPM conversion needs no additional engine ratio; using one again would count the reduction twice.',check:'Use circumference and diameter consistently. One is a distance around the tire and the other a distance across it. Also confirm whether the tire measurement is in inches or millimeters before using the 1,056 conversion constant.',question:'Can I convert axle RPM directly to MPH?',answer:'Yes, if the axle RPM is the driven-wheel RPM and the wheel is rolling without slip. Multiply by rolling circumference in inches and divide by 1,056.'},
 'tire-diameter-gearing':{formula:'Compensating reduction = old reduction × new rolling circumference/old rolling circumference',heading:'Calculate gearing compensation for larger tires',context:'Start with a 26-inch nominal tire and 4.10 final drive, keeping the preceding stages unchanged. The table compares the final ratio needed to preserve geometric engine RPM per road speed after a tire-diameter change.',steps:['Use rolling circumference measurements when available; otherwise label diameter-based results as nominal geometry.','Divide new tire dimension by the corresponding old dimension using the same measurement basis.','Multiply the existing final or overall reduction by that quotient.','Compare practical available gear choices and keep changes to tire mass, grip and fit separate from the RPM compensation.'],columns:['New diameter (in)','Required final reduction (:1)','RPM change if 4.10 retained (%)'],rows:[26,28,30].map(d=>[d,fixed(4.1*d/26),fixed((26/d-1)*100,2)]),interpretation:'At 30 inches, the ideal compensating final ratio is about 4.731:1. Retaining 4.10 instead lowers engine RPM at equal road speed by 13.33% in the circular no-slip geometry. The compensating ratio restores only this RPM/travel relationship, not every aspect of the original vehicle behavior.',check:'Do not describe this value as a fitment recommendation. A larger tire can change clearance, load, rotating inertia and braking behavior. Those effects are not reversed simply by restoring the RPM relationship.',question:'Should I compare diameter ratios or circumference ratios for tire gearing?',answer:'Either gives the same quotient for nominal circles. For measured loaded rolling behavior, compare the measured circumferences consistently rather than mixing a nominal diameter with a rolling measurement.'},
 'tire-speedometer':{formula:'Actual speed = indicated speed × new circumference/old circumference',heading:'Apply a tire-size speed correction conditionally',context:'This comparison assumes a rotation-based speed display calibrated to a nominal 26-inch tire, with no recalibration and no change in the sensor interpretation. Actual vehicle systems can use different signals and processing, so confirm that assumption first.',steps:['Identify whether the speed reading comes from rotation, GPS or another vehicle-specific system.','Compare new and original rolling circumference using the same method.','Multiply indicated speed by the new/old circumference quotient for the stated rotation-based case.','Use the appropriate manufacturer calibration procedure rather than treating nominal geometry as a finished instrument calibration.'],columns:['New nominal diameter (in)','Indicated speed (MPH)','Calculated actual speed (MPH)'],rows:[26,28,30].map(d=>[d,60,fixed(60*d/26,2)]),interpretation:'Larger tires travel farther per counted revolution, so the stated unchanged calibration underreads actual speed. With 30 inches instead of 26, an indicated 60 MPH corresponds to about 69.23 MPH in the model. This is a conditional correction, not a universal behavior of every dashboard.',check:'Do not apply the tire-circumference formula to an independent GPS speed measurement. Avoid mixing nominal tire dimensions with manufacturer revolutions-per-distance values unless the measurement conditions are understood.',question:'Does the same tire correction apply to odometer distance?',answer:'Under the same unchanged rotation-based calibration, actual distance scales by the same new/old rolling-circumference quotient. Verify how the specific vehicle derives distance before applying it.'},
 'quarter-mile-et-estimation':{formula:'ET(s) = 5.825 × (race weight_lb / mechanical HP)^(1/3)',heading:'Compare quarter-mile scenarios with the coefficient visible',context:'Fix race-ready weight at 3,200 lb and compare model horsepower inputs. The ET coefficient is held at 5.825. These are empirical model outputs, not promised passes, and the table does not simulate the launch or changes in traction.',steps:['Include driver, fuel and equipment in race-ready weight.','Keep the same power definition across every compared case.','Calculate the weight/power quotient and take its cube root before multiplying by the coefficient.','Use observed time slips to assess whether the model is representative; a reversible algebra check alone does not validate its prediction.'],columns:['Race weight (lb)','Model horsepower','Empirical ET (s)'],rows:[300,400,500].map(hp=>[3200,hp,fixed(5.825*Math.cbrt(3200/hp),3)]),interpretation:'The 400 hp case produces 11.65 seconds because 3,200/400 equals 8 and its cube root is 2. Increasing model power by 25% to 500 hp reduces the model ET by less than 25%, reflecting the cube-root relationship. That sensitivity should not be interpreted as a guaranteed improvement from an engine modification.',check:'Reaction time is separate from ET. Weight, power basis and the chosen empirical coefficient should stay visible in a comparison. Extra decimal places in the output do not remove uncertainty from traction, shifts, weather or the model itself.',question:'Can I use the ET formula backward to check its horsepower input?',answer:'Yes. Algebraically invert the same coefficient-based equation and it should return the original horsepower. This checks consistency of the calculation, not predictive accuracy for the vehicle.'},
 'trap-speed-horsepower':{formula:'Model MPH = 234 × (HP/weight_lb)^(1/3); model HP = weight_lb × (MPH/234)³',heading:'Inspect how trap speed changes inferred model power',context:'Fix weight at 3,200 lb and compare measured trap-speed inputs within the stated empirical model. Because the inverse is cubic, a small speed difference creates a larger proportional power difference. This sensitivity makes consistent measurements and model scope essential.',steps:['Record race-ready weight and the actual trap-speed measurement from the time slip.','Keep the coefficient and power definition consistent when comparing passes.','Cube MPH/234, then multiply by pounds for the inverse model horsepower.','Record wind and atmospheric conditions separately rather than assigning every speed difference to engine output.'],columns:['Trap speed input (MPH)','Race weight (lb)','Inferred model hp'],rows:[110,117,120].map(mph=>[mph,3200,fixed(3200*(mph/234)**3,2)]),interpretation:'At 117 MPH the model returns 400 hp for 3,200 lb. A 1% speed increase corresponds to a 3.0301% model-power increase at the same weight. The equation cannot distinguish additional engine power from aerodynamic, weight or condition differences that affect the actual pass.',check:'Trap speed is an end-of-run timing measurement, not the average speed of the entire run. Density altitude is a separate atmosphere calculation and does not automatically weather-correct this power estimate.',question:'Why is horsepower inferred from trap speed so sensitive to a small MPH change?',answer:'The model cubes the speed ratio. At unchanged weight, a speed factor of 1.01 becomes a horsepower factor of 1.01³, approximately 1.030301.'},
 'eighth-to-quarter-mile':{formula:'Estimated quarter-mile ET = eighth-mile ET × selected factor',heading:'Show conversion-factor uncertainty as a range',context:'Fix eighth-mile ET at 8.00 seconds and vary the factor rather than hiding it in the calculation. This example demonstrates a heuristic sensitivity comparison. It does not describe a universal relationship between the two distances or predict the second half of a particular run.',steps:['Collect paired eighth-mile and quarter-mile ETs from the same representative passes.','Divide each quarter-mile ET by its paired eighth-mile ET to inspect the observed factors.','Use a representative range rather than assuming the default is appropriate for another vehicle.','Repeat the comparison after a substantial gearing or power change, because second-half acceleration behavior may change.'],columns:['Eighth-mile ET (s)','Selected factor','Estimated quarter-mile ET (s)'],rows:[1.54,1.57,1.6].map(f=>[8,f,fixed(8*f,2)]),interpretation:'Changing the factor from 1.57 to 1.60 moves the result from 12.56 to 12.80 seconds even though the input pass is unchanged. A provisional range exposes that sensitivity more clearly than a single result displayed to many decimal places.',check:'Do not double ET simply because the distance doubles: the vehicle is already moving at the eighth-mile mark. Also do not treat this ET multiplier as a speed conversion or a calibrated bracket-racing dial-in.',question:'How do I estimate a conversion factor from my own time slips?',answer:'For each complete pass, divide quarter-mile ET by eighth-mile ET. Examine several representative paired passes and keep the factors tied to that vehicle and setup.'},
 'power-to-weight':{formula:'lb/hp = weight_lb/HP; hp/US short ton = HP × 2,000/weight_lb',heading:'Compare power-to-weight with consistent load states',context:'Hold mechanical horsepower at 400 and vary race-ready weight. Higher hp per short ton and lower pounds per horsepower describe the same directional improvement. The table uses US short tons, not metric tonnes.',steps:['Identify whether the power value is an engine rating, a measured engine output or measured wheel power.','Use comparable load states, including driver and appropriate fuel or equipment.','Choose a consistent unit convention and label both numerator and denominator.','Interpret the ratio alongside traction, gearing and power delivery rather than converting it directly into a promised acceleration time.'],columns:['Race-ready weight (lb)','Mechanical hp','lb/hp','hp/US short ton'],rows:[2800,3200,3600].map(w=>[w,400,w/400,fixed(400*2000/w,2)]),interpretation:'Adding 400 lb to the 3,200 lb case worsens the ratio from 8 to 9 lb/hp without changing engine power. The inverse measure falls from 250 to about 222.22 hp per US short ton. Keep the convention visible so a larger number is not mistakenly described as better in both columns.',check:'Do not compare mechanical hp per short ton directly with kW per metric tonne as if the numeric scales matched. A measured wheel-power input and a published engine rating also need a consistent measurement basis before drawing conclusions.',question:'How does adding a passenger affect power-to-weight?',answer:'Add the passenger and equipment to total mass while holding power unchanged. Power per unit mass falls, while mass per unit power rises. This alone does not determine the exact change in acceleration time.'},
 'torque-vs-horsepower':{formula:'P(W) = T(N·m) × RPM × 2π/60',heading:'Build a torque and power operating-point table',context:'Hold torque at 200 N·m and vary shaft RPM. This intentionally constant-torque example illustrates the power relationship; it is not a dynamometer curve for a real engine. A real curve uses the torque actually measured at each listed RPM.',steps:['Choose a torque value and the RPM at which that torque applies.','Convert lbf·ft to N·m if using the SI power equation.','Multiply torque by RPM × 2π/60 to obtain watts.','Divide watts by 1,000 for kW or by 745.6998716 for mechanical hp, keeping the measurement location identified.'],columns:['Shaft RPM','Torque (N·m)','Power (kW)','Mechanical hp'],rows:[2000,4000,6000].map(n=>[n,200,fixed(200*n*2*Math.PI/60000,3),fixed(200*n*2*Math.PI/60/745.6998716,2)]),interpretation:'With torque held constant, doubling shaft speed doubles power. This follows from doing the same rotational work per revolution twice as often. In an actual engine, torque may rise or fall with RPM, so power does not necessarily continue along this straight proportional relationship.',check:'Peak torque and peak horsepower often refer to different operating points. Do not pair the peak torque magnitude with the RPM at which peak power occurs unless the torque curve supports that combination.',question:'Why can horsepower rise after engine torque starts falling?',answer:'Power is torque multiplied by angular speed. If RPM increases proportionally faster than torque decreases, their product can still rise. Use values from the same operating point to calculate it.'},
 'sprocket-pitch-diameter':{formula:'D = p/sin(π/N); nominal travel per turn = Np',heading:'Compare pitch-circle geometry with chain advance',context:'The diameter formula locates pin centers, while travel per turn counts straight pitches. Both depend on tooth count, but they describe different geometry. Use the same nominal half-inch pitch in each calculation to isolate that distinction.',steps:['Identify the nominal pitch and count actual teeth.','Calculate pitch diameter using the sine half-angle in the correct angular mode.','Calculate nominal chain advance separately as tooth count multiplied by pitch.','Use manufacturer drawings for physical tooth-tip and clearance dimensions instead of treating the pitch circle as the component envelope.'],columns:['Teeth','Pitch diameter (in)','Nominal advance (in/rev)'],rows:[12,20,30].map(n=>[n,fixed(0.5/Math.sin(Math.PI/n),5),n*0.5]),interpretation:'The 20-tooth row has a pitch diameter of about 3.19623 inches and advances 10 inches of chain per turn. The pin-center circle is a useful mathematical reference, but the engaged chain consists of chords. That distinction is also why chain speed is calculated from Np rather than πD.',check:'If a measured outside diameter does not match this result, first confirm which diameter you measured. The model does not calculate tooth profile, bore, root diameter, wear or mounting tolerances.',question:'Can I scale a sprocket pitch diameter to another chain pitch?',answer:'At the same tooth count, diameter is directly proportional to nominal pitch. Doubling pitch doubles the calculated pitch diameter. This scaling alone does not establish compatible tooth profiles or interchangeable parts.'},
 'chain-drive-calculations':{formula:'Average chain speed = pitch × driver teeth × driver RPM/60',heading:'Connect chain travel, driver RPM and driven RPM',context:'Use half-inch pitch, a 12-tooth driver and a 60-tooth driven sprocket. Vary driver RPM to see both average linear chain speed and the driven shaft speed. The calculation assumes nominal tooth engagement and does not model slip or instantaneous chordal variation.',steps:['Convert pitch to the desired length unit and identify the driving shaft.','Multiply pitch by driver teeth for chain advance per revolution.','Multiply advance by driver revolutions per second for average chain speed.','Calculate driven RPM from driver RPM × driving teeth/driven teeth and compare both pitch-flow rates.'],columns:['Driver RPM','Driven RPM','Average chain speed (m/s)'],rows:[300,600,900].map(n=>[n,n*12/60,fixed(0.0127*12*n/60,3)]),interpretation:'At 600 driver rpm, the nominal advance is 6 inches per turn and average chain speed is 1.524 m/s. The 60-tooth driven sprocket turns at 120 rpm. Increasing driver RPM scales both results proportionally while the tooth-count ratio remains fixed.',check:'Do not use circular pitch circumference as nominal chain advance or use the driven tooth count with the driving RPM. Confirm consistent pitch flow: driver teeth × driver RPM should equal driven teeth × driven RPM.',question:'Do both sprockets have the same chain speed?',answer:'The same engaged chain passes both sprockets, so their average pitch flow is equal in the ideal model. Their shaft RPM differs according to tooth counts; instantaneous chordal behavior is outside this average-speed calculation.'},
};

export function workshopSections(slug:string):GuideSection[]{
 const w=guideWorkshops[slug];if(!w)return [];
 return [{heading:w.heading,text:w.context,formula:w.formula,steps:w.steps,table:{caption:w.heading+' — illustrative comparison, with the assumptions stated above',columns:w.columns,rows:w.rows},paragraphs:[w.interpretation]},{heading:'Check the inputs before interpreting a difference',text:w.check}];
}
